solve:{[tokens]
    int_vals:(); float_vals:(); sym_vals:(); junk_idxs:();
    i:0;

    is_int:{[s]
        if[not (count s) = 0;
            body:s;
            if[(first s) = "-";
                body:1_s;
                if[not (count body) = 0;
                    if[all body in "0123456789";
                        :1b;
                    ];
                ];
            ];
            if[(count body) > 0;
                if[all body in "0123456789";
                    :1b;
                ];
            ];
        ];
        :0b;
    };

    is_float:{[s]
        if[not (count s) = 0;
            body:s;
            if[(first s) = "-";
                body:1_s;
                if[not (count body) = 0;
                    parts:"." vs body;
                    if[(count parts) = 2;
                        pre:parts[0];
                        post:parts[1];
                        if[((count pre) > 0) and ((count post) > 0);
                            if[(all pre in "0123456789") and (all post in "0123456789");
                                :1b;
                            ];
                        ];
                    ];
                ];
            ];
        ];
        :0b;
    };

    is_sym:{[s]
        if[not (count s) = 0;
            if[all s in "abcdefghijklmnopqrstuvwxyz";
                :1b;
            ];
        ];
        :0b;
    };

    i:0;

    while[i < count[tokens];
        t:tokens[i];

        if[is_int[t];
            int_vals:int_vals,enlist "J"$t;
