                float_vals:float_vals,enlist val;
            ];

            if[not is_float[t];
                if[is_sym[t];
                    sym_vals:sym_vals,enlist t;
                ];

                if[not is_sym[t];
                    junk_idxs:junk_idxs,enlist i;
                ];
            ];
        ];

        i:i+1;
    ];

